marks={
'1':[(0,15),(0,19),(4,16),(4,18)],
'8':[(3,4),(4,8),(5,2),(7,8)],
'4':[(10,9),(10,11),(12,12),(14,10)],
'7':[(15,15),(18,15)],
'9':[(20,1),(20,5)]}
from collections import Counter
# best translations align marker sets: each translation means A + (dr,dc) overlaps B
for a in ['1','8','7','9']:
  for b in ['4','1','8','7','9']:
    if a==b: continue
    scores=Counter((rb-ra,cb-ca) for ra,ca in marks[a] for rb,cb in marks[b])
    best=scores.most_common(5)
    if best and best[0][1]>=2: print(a,'to',b,best)
